-- Generated from the reviewed 1844-entry snapshot. Executed transactionally by SQLx.
CREATE TABLE IF NOT EXISTS achievement_cleanup_backup (
  migration_id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TEMP TABLE canonical_achievements_013 (
  id TEXT PRIMARY KEY, category TEXT, name_pt_br TEXT, description_pt_br TEXT,
  reward_primogems INTEGER, version_id TEXT, order_index INTEGER
);
-- Backup BOTH orphan progress and obsolete catalog records before any deletion.
INSERT OR IGNORE INTO achievement_cleanup_backup (migration_id, payload)
SELECT '013', json_object(
 'catalog', json((SELECT json_group_array(json_object('id',id,'category',category,'name_pt_br',name_pt_br,'description_pt_br',description_pt_br,'reward_primogems',reward_primogems,'version_id',version_id,'order_index',order_index,'created_at',created_at)) FROM achievements WHERE id NOT IN (SELECT id FROM canonical_achievements_013))),
 'progress', json((SELECT json_group_array(json_object('profile_id',profile_id,'achievement_id',achievement_id,'completed',completed,'completed_at',completed_at,'notes',notes)) FROM profile_achievements WHERE achievement_id NOT IN (SELECT id FROM canonical_achievements_013)))
);
DELETE FROM profile_achievements WHERE achievement_id NOT IN (SELECT id FROM canonical_achievements_013);
DELETE FROM achievements WHERE id NOT IN (SELECT id FROM canonical_achievements_013);
SELECT * FROM canonical_achievements_013 WHERE true
ON CONFLICT(id) DO UPDATE SET category=excluded.category,name_pt_br=excluded.name_pt_br,description_pt_br=excluded.description_pt_br,reward_primogems=excluded.reward_primogems,version_id=excluded.version_id,order_index=excluded.order_index;
DROP TABLE canonical_achievements_013;
